/**
 * @distilled.cloud/anthropic -- Claude Platform (Anthropic) API SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy models
 * that `scripts/convert.ts` converts from the OpenAPI document mirrored at
 * `specs/spec-mirror-anthropic/specs/openapi.json`. Everything else in this
 * folder is hand-written.
 *
 * One module per API area: `messages`, `models`, `files`, `skills`,
 * `userProfiles` and `organizations` (the Admin API), and a `beta*` twin of
 * each area with beta routes -- among them the managed agents platform
 * (`betaAgents`, `betaEnvironments`, `betaSessions`).
 *
 * @example
 * ```ts
 * import * as Anthropic from "@distilled.cloud/anthropic";
 *
 * const message = yield* Anthropic.messages.createMessage({
 *   model: "claude-opus-4-8",
 *   max_tokens: 1024,
 *   messages: [{ role: "user", content: "Hello, Claude" }],
 * });
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export { AnthropicProtocol, type AnthropicOpError, type AnthropicOpContext } from "./protocol.ts";
export { paginateCursor, paginateRelay } from "./pagination.ts";
export * as Retry from "./retry.ts";
export * from "./services/index.ts";
